mapper.select:
select info.PROD_ID ,INFO.PROD_NAME ,INFO.PROD_RE ,INFO.ISSUING_WAY ,INFO.PROFIT_TYPE /**运作方式**/ ,INFO.SET_DATE /**成立日**/ from REP_PROD_INFO info where REP_PROD_TYPE in ('02','03') /**母产品或者单产品**/ AND info.STATUS='E'
AND info.P_PROD_ID=#{pprodid,jdbcType=VARCHAR}
order by info.PROD_ID

select rownum personalField ,info.PROD_ID ,rindex.ASSETS_VALUE ,rindex.UNIT_VALUE ,rindex.UNIT_VALUE_T ,nvl(bal.OTHER_FEE,0) otherFee from REP_PROD_INFO info left join REP_PROD_INDEX rindex on info.PROD_ID=rindex.PROD_ID and rindex.VALUE_DATE=#{reportDate,jdbcType=DATE} left join ( SELECT bb.BOOKSET_ID ,bb.BALANCE_DATE ,nvl(sum(TDY_O_D_AMT),0) OTHER_FEE from BOK_BALANCE bb WHERE 1=1 AND bb.STATUS='E' and bb.SUBJECT_NO in ( '6407','6605' )
and bb.BALANCE_DATE=#{reportDate,jdbcType=DATE}
group by bb.BOOKSET_ID,bb.BALANCE_DATE ) bal on info.PROD_ID=bal.BOOKSET_ID where 1=1 and info.STATUS='E' and info.REP_PROD_TYPE in ('02','03') /**单产品或者子产品**/
and info.P_PROD_ID=#{pprodid,jdbcType=VARCHAR}
order by info.PROD_ID

select rownum personalField ,rindex.PRI_ID ,rindex.INDEX_NAME ,rindex.INDEX_VALUE from REP_INDEX_SUB rindex where AUDIT_STATUS='E'
and rindex.PRI_ID=#{indexId,jdbcType=VARCHAR}
and #{reportDate,jdbcType=DATE} between rindex.EFF_DATE and rindex.END_DATE

select rownum personalField ,dpa.PROD_ID ,dpa.FIX_PRE_RATIO ,dpa.FIX_AFTER_RATIO ,dpa.EQUITY_PRE_RATIO ,dpa.EQUITY_AFTER_RATIO ,dpa.FD_PRE_RATIO ,dpa.FD_AFTER_RATIO ,dpa.MIX_PRE_RATIO ,dpa.MIX_AFTER_RATIO from DIS_PROD_ASSET dpa where dpa.DATA_STATUS='E'
and PROD_ID=#{prodid,jdbcType=VARCHAR}
and #{reportDate,jdbcType=DATE} between dpa.EFF_DATE and dpa.EFF_END_DATE

select rownum personalField ,rac.PROD_ID ,rac.PUB_DATE ,rac.ASSETS_CODE ,rac.ASSETS_NAME ,rac.FAIR_VALUE ,rac.PD_PROP from REP_ASSETS_COMB rac where rac.STATUS='E'
and rac.PROD_ID=#{prodid,jdbcType=VARCHAR}
and rac.PUB_DATE = #{reportDate,jdbcType=DATE}
order by rac.PD_PROP desc,rac.FAIR_VALUE desc

select rownum personalField ,deal.PROD_ID ,deal.PUB_DATE ,deal.BANK_TRANS_AMT ,deal.ORG_TRANS_AMT ,deal.INVEST_TRANS_AMT ,deal.RELATEAMOUNT from REP_REL_DEAL deal where deal.STATUS='E'
and deal.PROD_ID=#{prodid,jdbcType=VARCHAR}
and #{reportDate,jdbcType=DATE} between EFFDATE and EFFDELIDATE

select info.PROD_ID, bal.* from REP_PROD_INFO info left join ( SELECT bb.BOOKSET_ID ,bb.BALANCE_DATE ,nvl(sum(TDY_O_D_AMT),0) OTHER_FEE from BOK_BALANCE bb WHERE 1=1 AND bb.STATUS='E' and bb.SUBJECT_NO in ( '6407','6605' )
and bb.BALANCE_DATE=#{reportDate,jdbcType=DATE}
group by bb.BOOKSET_ID,bb.BALANCE_DATE ) bal on info.PROD_ID=bal.BOOKSET_ID where 1=1 and info.STATUS='E'
and info.P_PROD_ID=#{pprodid,jdbcType=VARCHAR}

select info.PROD_ID ,basis.EFF_DATE EFF_DATE ,basis.DATA_TYPE ,basis.PROPORTION ,basis.GROUP_ID ,basis.STATUS ,basis.UPDATE_TIME from REP_PROD_INFO info left join REP_PROD_BASIC_CHANGE basis on info.PROD_ID=basis.PROD_ID where 1=1 and info.REP_PROD_TYPE in ('02','03') /**单产品或者子产品**/
and info.PROD_ID=#{prodId,jdbcType=VARCHAR}
and info.STATUS=#{status,jdbcType=VARCHAR}
order by basis.EFF_DATE
